        /**
          * Text colour
          * @default 'blue'
         */
        "color": IoLinkColor;
        /**
          * Disables the link — removes href and blocks click
          * @default false
         */
        "disabled": boolean;
        /**
          * Downloadable file name. Enables download behavior on click.
         */
        "download": string | undefined;
